fn solve(x: i32) -> i32 {
    // Convert x to string to easily access digits and length
    let x_str = x.to_string();
    let first_digit = x_str.chars().next().unwrap().to_digit(10).unwrap() as i32;
    let length = x_str.len() as i32;
    
    // Calculate the score
    // For each digit before the current digit: 1 + 2 + 3 + 4 = 10 presses
    let presses_before_digit = (first_digit - 1) * 10;
    
    // For the current digit: sum of 1..length
    let presses_for_current_digit = (length * (length + 1)) / 2;
    
    presses_before_digit + presses_for_current_digit
}